// Wasm modules for the tests, as bytes rather than files.
//
// Inline, because a .wasm file in the tree is unreadable in review and a
// build step that produces one would make the suite depend on wabt's
// wat2wasm, which exists only in a Wasm-enabled build directory. The WAT each
// array was assembled from is kept beside it, so anything here can be checked
// or regenerated with:
//
//     wat2wasm module.wat -o module.wasm
//
// wat2wasm is built at <build dir>/hermes/external/wabt/wabt/wat2wasm when
// HERMES_ENABLE_WASM is on.

'use strict';

// (module
//   (memory (export "m") 1)
//   (func (export "add") (param i32 i32) (result i32)
//     (i32.add (local.get 0) (local.get 1))))
//
// The smallest module that still has both a function and a memory to export.
exports.ADD = new Uint8Array([
  0x00, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00, 0x01, 0x07, 0x01, 0x60,
  0x02, 0x7f, 0x7f, 0x01, 0x7f, 0x03, 0x02, 0x01, 0x00, 0x05, 0x03, 0x01,
  0x00, 0x01, 0x07, 0x0b, 0x02, 0x01, 0x6d, 0x02, 0x00, 0x03, 0x61, 0x64,
  0x64, 0x00, 0x00, 0x0a, 0x09, 0x01, 0x07, 0x00, 0x20, 0x00, 0x20, 0x01,
  0x6a, 0x0b,
]);

// (module
//   (import "env" "log" (func $log (param i32)))
//   (memory (export "mem") 1)
//   (global $counter (mut i32) (i32.const 0))
//   (table 2 funcref)
//   (elem (i32.const 0) $fib $ident)
//   (type $t (func (param i32) (result i32)))
//
//   (func $fib (export "fib") (param $n i32) (result i32)
//     (global.set $counter (i32.add (global.get $counter) (i32.const 1)))
//     (if (result i32) (i32.lt_s (local.get $n) (i32.const 2))
//       (then (local.get $n))
//       (else
//         (i32.add
//           (call $fib (i32.sub (local.get $n) (i32.const 1)))
//           (call $fib (i32.sub (local.get $n) (i32.const 2)))))))
//   (func (export "calls") (result i32) (global.get $counter))
//   (func (export "mul64") (param i64 i64) (result i64)
//     (i64.mul (local.get 0) (local.get 1)))
//   (func $ident (param i32) (result i32) (local.get 0))
//   (func (export "dist") (param f64 f64) (result f64)
//     (f64.sqrt (f64.add (f64.mul (local.get 0) (local.get 0))
//                        (f64.mul (local.get 1) (local.get 1)))))
//   (func (export "poke") (param $a i32) (param $v i32)
//     (i32.store (local.get $a) (local.get $v)))
//   (func (export "peek") (param $a i32) (result i32)
//     (i32.load (local.get $a)))
//   (func (export "indirect") (param $i i32) (param $x i32) (result i32)
//     (call_indirect (type $t) (local.get $x) (local.get $i)))
//   (func (export "shout") (param i32) (call $log (local.get 0)))
//   (func (export "boom") (result i32) (unreachable))
//   (func (export "divzero") (param i32) (result i32)
//     (i32.div_s (local.get 0) (i32.const 0))))
//
// Everything a real toolchain emits and this layer has to carry: recursion,
// a mutable global, i64 (which crosses to JS as BigInt), f64 math, linear
// memory shared with JS, a table reached through call_indirect, an imported
// JS function, and two ways to trap.
